@{
        var o = new JObject();
        o["kind"] = "forwarded-headers";
        o["request_id"] = (string)context.Variables["reqId"];
        o["method"] = context.Request.Method;
        o["api_key_header"] = context.Request.Headers.ContainsKey("api-key");
        o["subscription_key_header"] = context.Request.Headers.ContainsKey("Ocp-Apim-Subscription-Key");
        o["authorization_header"] = context.Request.Headers.ContainsKey("Authorization");
        o["api_key_query"] = context.Request.Url.Query.ContainsKey("api-key");
        o["subscription_key_query"] = context.Request.Url.Query.ContainsKey("subscription-key");
        return o.ToString(Newtonsoft.Json.Formatting.None);
      }

@{
            try {
              var b = context.Request.Body.As(preserveContent: true);
              var o = new JObject();
              o["request_id"] = (string)context.Variables["reqId"];
              o["path"] = context.Request.Url.Path;
              var ua = context.Request.Headers.GetValueOrDefault("User-Agent", "");
              o["user_agent"] = ua.Length > 80 ? ua.Substring(0, 80) : ua;
              o["keys"] = string.Join(",", b.Properties().Select(p => p.Name));
              o["model"] = (string)b["model"];
              o["stream"] = b["stream"] == null ? "absent" : b["stream"].ToString();
              o["has_max_tokens"] = b["max_tokens"] != null;
              o["has_max_completion_tokens"] = b["max_completion_tokens"] != null;
              var msgs = b["messages"] as JArray;
              o["message_count"] = msgs == null ? 0 : msgs.Count;
              o["roles"] = msgs == null ? "" : string.Join(",", msgs.Select(m => (string)m["role"]));
              var tools = b["tools"] as JArray;
              o["tool_names"] = tools == null ? "" : string.Join(",", tools.Select(t => t["function"] != null ? (string)t["function"]["name"] : (string)t["type"]));
              var tc = b["tool_choice"] == null ? "absent" : b["tool_choice"].ToString(Newtonsoft.Json.Formatting.None);
              o["tool_choice"] = tc.Length > 100 ? tc.Substring(0, 100) : tc;
              o["tool_count"] = tools == null ? 0 : tools.Count;
              o["has_tool_choice"] = b["tool_choice"] != null;
              try {
                var nums = new JObject();
                foreach (var prop in b.Properties()) {
                  var val = prop.Value as JValue;
                  if (val != null && (val.Value is long || val.Value is double || val.Value is bool)) {
                    nums[prop.Name] = val.DeepClone();
                  }
                }
                var sopts = b["stream_options"] as JObject;
                if (sopts != null) {
                  var snums = new JObject();
                  foreach (var sprop in sopts.Properties()) {
                    var sval = sprop.Value as JValue;
                    if (sval != null && (sval.Value is long || sval.Value is double || sval.Value is bool)) {
                      snums[sprop.Name] = sval.DeepClone();
                    }
                  }
                  nums["stream_options"] = snums;
                }
                o["params"] = nums;
              } catch (Exception) {
                o["params"] = "unavailable";
              }
              return o.ToString(Newtonsoft.Json.Formatting.None);
            } catch (Exception) {
              return "request-shape-unavailable";
            }
          }
